#include <stdio.h>
#define INF 9999

int main()
{
    int n, i, j, k;
    int cost[20][20];
    int visited[20] = {0};
    int total = 0;
    int min, u, v;

    printf("Enter number of vertices: ");
    scanf("%d", &n);

    printf("Enter cost matrix (use 0 for self/no edge):\n");
    for (i = 0; i < n; i++)
    {
        for (j = 0; j < n; j++)
        {
            scanf("%d", &cost[i][j]);

            if (cost[i][j] == 0)
            {
                cost[i][j] = INF;
            }
        }
    }

    visited[0] = 1;
    printf("\nSelected MST Edges:\n");

    for (k = 0; k < n - 1; k++)
    {
        min = INF;
        u = 0;
        v = 0;

        for (i = 0; i < n; i++)
        {
            if (visited[i])
            {
                for (j = 0; j < n; j++)
                {
                    if (!visited[j] && cost[i][j] < min)
                    {
                        min = cost[i][j];
                        u = i;
                        v = j;
                    }
                }
            }
        }

        visited[v] = 1;
        printf("Edge %d: (%d -> %d) with Cost = %d\n", k + 1, u, v, min);
        total += min;
    }

    printf("Total MST Cost = %d\n", total);

    return 0;
}

