int set[20], chosen[20];
int n, target, found = 0;

void findSubsets(int index, int sum)
{
    int i;

    if (sum == target)
    {
        found = 1;
        printf("{ ");

        for (i = 0; i < index; i++)
        {
            if (chosen[i])
            {
                printf("%d ", set[i]);
            }
        }

        printf("}\n");
        return;
    }

    if (index == n || sum > target)
    {
        return;
    }

    chosen[index] = 1;
    findSubsets(index + 1, sum + set[index]);

    chosen[index] = 0;
    findSubsets(index + 1, sum);
}

int main()
{
