#include <stdio.h>
#include <stdlib.h>

int board[20];
int n;

int isSafe(int row, int col)
{
    int i;

    for (i = 0; i < row; i++)
    {
        if (board[i] == col || abs(board[i] - col) == abs(i - row))
        {
            return 0;
        }
    }

    return 1;
}

int solve(int row)
{
    int col;

    if (row == n)
    {
        return 1;
    }

    for (col = 0; col < n; col++)
    {
        if (isSafe(row, col))
        {
            board[row] = col;

            if (solve(row + 1))
            {
                return 1;
            }
        }
    }

    return 0;
}

int main()
{
    int i, j;

    printf("Enter number of Queens (N): ");
    scanf("%d", &n);

    if (solve(0))
    {
        printf("\nSolution board placement:\n");

        for (i = 0; i < n; i++)
        {
            for (j = 0; j < n; j++)
            {
                if (board[i] == j)
                {
                    printf("Q ");
                }
                else
                {
                    printf(". ");
                }
            }
            printf("\n");
        }
    }
    else
    {
        printf("No valid placement exists for N = %d.\n", n);
    }

    return 0;
}

